package com.dtm.platform.service;import com.dtm.platform.entity.*;import com.dtm.platform.repository.*;import com.dtm.platform.exception.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import java.nio.file.*;import java.util.*;import java.io.*;
@Service public class MediaService {
 private final MediaRepository media;private final Path root;public MediaService(MediaRepository media,@Value("${app.upload-dir}")String root){this.media=media;this.root=Path.of(root).toAbsolutePath().normalize();}
 @Transactional public Media upload(MultipartFile file)throws IOException{if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("File must be 1 byte to 10 MB");byte[] bytes=file.getBytes();String type=sniff(bytes);String name=Optional.ofNullable(file.getOriginalFilename()).orElse("upload").replaceAll("[^a-zA-Z0-9 ._-]","_");if(name.length()>200)name=name.substring(name.length()-200);var m=new Media();m.name=name;m.storageKey=UUID.randomUUID().toString();m.contentType=type;m.size=bytes.length;Files.createDirectories(root);Path path=root.resolve(m.storageKey);Files.write(path,bytes,StandardOpenOption.CREATE_NEW);try{return media.saveAndFlush(m);}catch(RuntimeException e){Files.deleteIfExists(path);throw e;}}
 private String sniff(byte[] b){if(b.length>=5&&new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))return "application/pdf";if(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71)return "image/png";if(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return "image/jpeg";if(b.length>=12&&new String(b,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(b,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP"))return "image/webp";throw new IllegalArgumentException("Only PDF, PNG, JPEG and WebP are supported");}
 @Transactional(readOnly=true) public Media record(long id){return media.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"File not found."));}
 public byte[] bytes(Media m)throws IOException{Path path=root.resolve(m.storageKey).normalize();if(!path.startsWith(root))throw new IllegalArgumentException("Invalid path");return Files.readAllBytes(path);}
 @Transactional(readOnly=true) public boolean publicReference(long id){return (entityManager.createQuery("select count(r) from Resume r where r.published=true and r.media.id=:id",Long.class).setParameter("id",id).getSingleResult()>0 || entityManager.createQuery("select count(p) from Project p where p.published=true and p.body like :ref",Long.class).setParameter("ref","%/api/v1/media/"+id+"/download%").getSingleResult()>0);}
 @jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager entityManager;
@Transactional public Media rename(long id,String name){if(name==null||!name.matches("[A-Za-z0-9 ._-]{1,200}"))throw new IllegalArgumentException("Use a filename of 1–200 characters");var m=record(id);m.name=name;return media.saveAndFlush(m);}
 @Transactional public void delete(long id)throws IOException{var m=record(id);long resumes=entityManager.createQuery("select count(r) from Resume r where r.media.id=:id",Long.class).setParameter("id",id).getSingleResult();long projects=entityManager.createQuery("select count(p) from Project p where p.body like :ref",Long.class).setParameter("ref","%/api/v1/media/"+id+"/download%").getSingleResult();if(resumes+projects>0)throw new ApiException(HttpStatus.CONFLICT,"Remove content references before deleting this file.");media.delete(m);media.flush();Files.deleteIfExists(root.resolve(m.storageKey));}
}
